def eval_expr(s):
    idx = 0
    n = len(s)

    def skip_ws():
        nonlocal idx
        while idx < n and s[idx].isspace():
            idx += 1

    def parse_number():
        nonlocal idx
        start = idx
        while idx < n and s[idx].isdigit():
            idx += 1
        return int(s[start:idx])

    def parse_factor():
        nonlocal idx
        skip_ws()
        if idx >= n:
            raise ValueError("Unexpected end of expression")
        c = s[idx]
        if c == '-':
            idx += 1
            return -parse_factor()
        elif c == '+':
            idx += 1
            return parse_factor()
        elif c == '(':
            idx += 1
            val = parse_expr()
            skip_ws()
            if idx < n and s[idx] == ')':
                idx += 1
            else:
                raise ValueError("Missing closing parenthesis")
            return val
        elif c.isdigit():
            return parse_number()
        else:
            raise ValueError(f"Unexpected character: {c}")

    def parse_term():
        val = parse_factor()
        skip_ws()
        while idx < n and s[idx] in ('*', '/'):
            op = s[idx]
            idx += 1
            val = val * parse_factor() if op == '*' else val / parse_factor()
            skip_ws()
        return val

    def parse_expr():
        val = parse_term()
        skip_ws()
        while idx < n and s[idx] in ('+', '-'):
            op = s[idx]
            idx += 1
            val = val + parse_term() if op == '+' else val - parse_term()
            skip_ws()
        return val

    skip_ws()
    if idx == n:
        raise ValueError("Empty expression")
    result = parse_expr()
    skip_ws()
    if idx < n:
        raise ValueError("Unexpected characters at end")
    return float(result)
