def topo_count(n, edges):
    in_mask = [0] * n
    for u, v in edges:
        in_mask[v] |= (1 << u)

    dp = [0] * (1 << n)
    dp[0] = 1

    for mask in range(1, 1 << n):
        count = 0
        for i in range(n):
            if mask & (1 << i) and (in_mask[i] & mask) == in_mask[i]:
                count += dp[mask ^ (1 << i)]
        dp[mask] = count

    return dp[-1]
